    description: "Le Milan noir est peut-être le rapace le plus nombreux au monde. Opportuniste, il se nourrit de charognes, vole de la nourriture et capture de petits animaux. La sous-espèce orientale (milan à oreilles noires) niche dans toute la Mongolie et se rassemble en grand nombre autour d’Oulan-Bator, des camps de yourtes, des décharges et du bétail. Il arrive en avril et repart en septembre vers l’Asie du Sud.",
