    description: "Le Pélican frisé niche en colonies dispersées du sud-est de l’Europe à la Mongolie et à la Chine. La population mongole, qui nichait au lac Khar Us et sur d’autres lacs de l’ouest, a presque disparu — on l’estimait à quelques couples seulement. Le braconnage pour son bec (utilisé comme racloir à chevaux) et le dérangement en sont les principales causes. Il n’y a plus que des mentions occasionnelles dans l’ouest et le Gobi.",
